def _tier(code, title, count=None, days=None, amount=None):
    def condition(value, days_condition=False):
        item = {"enabled": value is not None, "value": value}
        if not days_condition:
            item["operator"] = "gte"
        return item

    return {
        "code": code,
        "title": title,
        "enabled": True,
        "conditions": {
            "purchase_count": condition(count),
            "days_since_last": condition(days, days_condition=True),
            "lifetime_amount": condition(amount),
        },
    }


